#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        ElectricInductance::new(v, ElectricInductanceUnit::Henry),
        ElectricInductance::from_henries(v)
    );
    assert_eq!(
        ElectricInductance::from_base(v).convert_to(ElectricInductanceUnit::Henry),
        ElectricInductance::from_base(v).as_henries()
    );
    assert_eq!(
        ElectricInductance::new(v, ElectricInductanceUnit::Picohenry),
        ElectricInductance::from_picohenries(v)
    );
    assert_eq!(
        ElectricInductance::from_base(v).convert_to(ElectricInductanceUnit::Picohenry),
        ElectricInductance::from_base(v).as_picohenries()
    );
    assert_eq!(
        ElectricInductance::new(v, ElectricInductanceUnit::Nanohenry),
        ElectricInductance::from_nanohenries(v)
    );
    assert_eq!(
        ElectricInductance::from_base(v).convert_to(ElectricInductanceUnit::Nanohenry),
        ElectricInductance::from_base(v).as_nanohenries()
    );
    assert_eq!(
        ElectricInductance::new(v, ElectricInductanceUnit::Microhenry),
        ElectricInductance::from_microhenries(v)
    );
    assert_eq!(
        ElectricInductance::from_base(v).convert_to(ElectricInductanceUnit::Microhenry),
        ElectricInductance::from_base(v).as_microhenries()
    );
    assert_eq!(
        ElectricInductance::new(v, ElectricInductanceUnit::Millihenry),
        ElectricInductance::from_millihenries(v)
    );
    assert_eq!(
        ElectricInductance::from_base(v).convert_to(ElectricInductanceUnit::Millihenry),
        ElectricInductance::from_base(v).as_millihenries()
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "H".parse::<ElectricInductanceUnit>(),
        Ok(ElectricInductanceUnit::Henry)
    );
    assert_eq!(
        format!("2.5 {}", "H").parse::<ElectricInductance>(),
        Ok(ElectricInductance::new(2.5, ElectricInductanceUnit::Henry))
    );
    assert_eq!(
        "pH".parse::<ElectricInductanceUnit>(),
        Ok(ElectricInductanceUnit::Picohenry)
    );
    assert_eq!(
        format!("2.5 {}", "pH").parse::<ElectricInductance>(),
        Ok(ElectricInductance::new(
            2.5,
            ElectricInductanceUnit::Picohenry
        ))
    );
    assert_eq!(
        "nH".parse::<ElectricInductanceUnit>(),
        Ok(ElectricInductanceUnit::Nanohenry)
    );
    assert_eq!(
        format!("2.5 {}", "nH").parse::<ElectricInductance>(),
        Ok(ElectricInductance::new(
            2.5,
            ElectricInductanceUnit::Nanohenry
        ))
    );
    assert_eq!(
        "µH".parse::<ElectricInductanceUnit>(),
        Ok(ElectricInductanceUnit::Microhenry)
    );
    assert_eq!(
        format!("2.5 {}", "µH").parse::<ElectricInductance>(),
        Ok(ElectricInductance::new(
            2.5,
            ElectricInductanceUnit::Microhenry
        ))
    );
    assert_eq!(
        "mH".parse::<ElectricInductanceUnit>(),
        Ok(ElectricInductanceUnit::Millihenry)
    );
    assert_eq!(
        format!("2.5 {}", "mH").parse::<ElectricInductance>(),
        Ok(ElectricInductance::new(
            2.5,
            ElectricInductanceUnit::Millihenry
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricInductance>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = ElectricInductance::from_base(6.0);
    let b = ElectricInductance::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = ElectricInductance::<i64>::from_base(7);
    let b = ElectricInductance::<i64>::from_base(2);
    assert_eq!(a + b, ElectricInductance::from_base(9));
    assert_eq!(a % b, ElectricInductance::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<ElectricInductance<i64>>(),
        ElectricInductance::from_base(9)
    );
}
